      try {
        setup(ctx);
      } catch (err) {
        for (const dispose of disposers) {
          try {
            dispose();
          } catch {}
        }
        throw err;
      }
    },

    updated(this: ViewHookInternal): void {
      const state = HOOK_STATE.get(this);
      if (!state) return;
