const fetchPrefetchNav = (audioUrl: string): void => {
  const navUrl = navUrlFor(audioUrl);
  fetch(navUrl)
    .then((r) => {
      if (!r.ok) throw new Error(`HTTP ${r.status}`);
      return r.json();
