    .then((data: JsonValue) => {
      if (prefetchedFor !== audioUrl) return; // target changed mid-flight
      prefetchedNav = parseChapterWindow(data);
      log("prefetch-nav-done", {
        url: navUrl,
        hasNext: prefetchedNav?.next !== null,
      });
    })
    .catch((err: Error) => {
      log("prefetch-nav-fail", { url: navUrl, error: String(err) });
    });
};

